CREATE TYPE task_status AS ENUM ('todo', 'in_progress', 'completed');
CREATE TABLE tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, assigned_to UUID REFERENCES users(id) ON DELETE SET NULL, created_by UUID NOT NULL REFERENCES users(id), title TEXT NOT NULL CHECK (char_length(title) BETWEEN 2 AND 160), description TEXT CHECK (char_length(description) <= 2000), due_date DATE, status task_status NOT NULL DEFAULT 'todo', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE announcements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, author_id UUID NOT NULL REFERENCES users(id), message TEXT NOT NULL CHECK (char_length(message) BETWEEN 2 AND 2000), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE project_resources (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, added_by UUID NOT NULL REFERENCES users(id), label TEXT NOT NULL CHECK (char_length(label) BETWEEN 2 AND 120), url TEXT NOT NULL CHECK (url ~* '^https://'), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE milestones (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL CHECK (char_length(title) BETWEEN 2 AND 160), due_date DATE, completed_at TIMESTAMPTZ);
CREATE INDEX tasks_project_status_idx ON tasks(project_id, status, due_date);
CREATE INDEX announcements_project_idx ON announcements(project_id, created_at DESC);
